package ru.hryushki.clients;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;
import org.junit.runner.RunWith;
import org.json.*;
import java.math.*;
import java.time.*;
import java.io.*;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class CrmTest {
 static JSONObject sample()throws Exception{JSONObject d=Model.empty();JSONObject c=new JSONObject("{\"id\":\"client-a\",\"name\":\"Анна\",\"city\":\"Москва\",\"channel\":\"ВК\"}");Model.upsert(d,"clients",c);return d;}
 static JSONObject order(JSONObject d)throws Exception{JSONObject o=Model.newOrder(d,"client-a");JSONObject i=new JSONObject("{\"name\":\"Лежанка\",\"sku\":\"LZ-001\",\"color\":\"Зелёный флис\",\"qty\":2,\"price\":680}");Model.rows(o,"items").put(i);return o;}
 static void amount(String expected,BigDecimal actual){assertEquals(0,new BigDecimal(expected).compareTo(actual));}
 @Test public void deadlinesAndTotals()throws Exception{JSONObject d=sample(),o=order(d);assertEquals(LocalDate.now().plusDays(3),Model.date(Model.s(o,"due")));o.put("deliveryCost","150.50");o.put("prepaid",500);Model.upsert(d,"orders",o);amount("1510.50",Model.total(o));amount("1010.50",Model.total(o).subtract(Model.n(o,"prepaid")));assertTrue(Model.needsShipping(o));}
 @Test public void decimalPrecision()throws Exception{JSONObject d=sample(),o=order(d);Model.rows(o,"items").getJSONObject(0).put("price","0.10");o.put("deliveryCost","0.10");amount("0.30",Model.total(o));o.put("prepaid","0.31");try{Model.upsert(d,"orders",o);fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("Предоплата"));}}
 @Test public void invalidDatesAndComposition()throws Exception{try{Model.date("31.02.2026");fail();}catch(IllegalArgumentException expected){}JSONObject d=sample(),o=order(d);o.put("due",Model.day(LocalDate.now().minusDays(1)));try{Model.validateOrder(d,o);fail();}catch(IllegalArgumentException expected){}o.put("due",Model.today());o.put("items",new JSONArray());try{Model.validateOrder(d,o);fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("изделие"));}}
 @Test public void statusRequiresActualShipment()throws Exception{JSONObject d=sample(),o=order(d);o.put("status","Отправлен");try{Model.validateOrder(d,o);fail();}catch(IllegalArgumentException expected){}o.put("shipped",Model.today());Model.validateOrder(d,o);assertFalse(Model.needsShipping(o));o.put("status","Доставлен");try{Model.validateOrder(d,o);fail();}catch(IllegalArgumentException expected){}o.put("delivered",Model.today());Model.validateOrder(d,o);assertFalse(Model.openOrder(o));}
 @Test public void wishConversionIsLinkedAndIdempotent()throws Exception{JSONObject d=sample();JSONObject w=new JSONObject("{\"id\":\"wish-a\",\"clientId\":\"client-a\",\"product\":\"Тоннель\",\"color\":\"Листья\",\"qty\":2,\"status\":\"Ожидает\",\"kind\":\"Пожелание\"}");Model.upsert(d,"wishes",w);assertEquals(0,Model.rows(d,"orders").length());JSONObject o=Model.convertWish(d,"wish-a");assertEquals("Листья",Model.rows(o,"items").getJSONObject(0).getString("color"));assertEquals(Model.today(),Model.s(o,"placed"));assertEquals(1,Model.rows(d,"orders").length());assertEquals(Model.s(o,"id"),Model.s(Model.convertWish(d,"wish-a"),"id"));assertEquals(1,Model.rows(d,"orders").length());assertEquals("Заказ создан",Model.s(Model.find(d,"wishes","wish-a"),"status"));Model.validate(d);}
 @Test public void reminderEventsAndCancellation()throws Exception{JSONObject d=sample(),o=order(d);o.put("placed","01.11.2026");o.put("due","05.11.2026");o.put("expected","10.11.2026");Model.upsert(d,"orders",o);ZoneId z=ZoneId.of("Asia/Omsk");long now=LocalDate.of(2026,11,4).atTime(8,0).atZone(z).toInstant().toEpochMilli();java.util.List<Model.Event> events=Model.events(d,now,z);assertEquals(3,events.size());assertTrue(events.stream().anyMatch(e->e.key.startsWith("early:")));assertTrue(events.stream().anyMatch(e->e.key.startsWith("ship:")&&e.at==LocalDate.of(2026,11,5).atTime(9,0).atZone(z).toInstant().toEpochMilli()));o.put("status","Отправлен");o.put("shipped","05.11.2026");Model.upsert(d,"orders",o);assertEquals(1,Model.events(d,now,z).size());o.put("status","Отменён");Model.upsert(d,"orders",o);assertEquals(0,Model.events(d,now,z).size());}
 @Test public void overdueOncePerDayAndDeliveryDateEdit()throws Exception{JSONObject d=sample(),o=order(d);o.put("placed","01.11.2026");o.put("due","02.11.2026");Model.upsert(d,"orders",o);ZoneId z=ZoneId.of("Asia/Omsk");long now=LocalDate.of(2026,11,8).atTime(11,0).atZone(z).toInstant().toEpochMilli();java.util.List<Model.Event> events=Model.events(d,now,z);assertEquals(1,events.size());assertTrue(events.get(0).key.startsWith("overdue:"));o.put("status","Отправлен");o.put("shipped","02.11.2026");o.put("expected","10.11.2026");Model.upsert(d,"orders",o);String old=Model.events(d,now,z).get(0).key;o.put("expected","11.11.2026");Model.upsert(d,"orders",o);assertNotEquals(old,Model.events(d,now,z).get(0).key);}
 @Test public void editingAuditAndRoundTrip()throws Exception{JSONObject d=sample(),o=order(d);Model.upsert(d,"orders",o);JSONObject edit=Model.copy(o);edit.put("note","Положить открытку");Model.upsert(d,"orders",edit);JSONObject last=Model.rows(d,"audit").getJSONObject(Model.rows(d,"audit").length()-1);assertEquals("edit",Model.s(last,"action"));assertFalse(last.getJSONObject("before").has("note"));JSONObject parsed=Store.parse(d.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));assertEquals("Положить открытку",Model.s(Model.find(parsed,"orders",Model.s(o,"id")),"note"));}
 @Test public void rejectAccountingDatabase()throws Exception{try{Store.parse("{\"version\":2,\"operations\":[]}".getBytes());fail();}catch(IllegalArgumentException expected){}}
 @Test public void persistenceBackupAndRestore()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);JSONObject d=sample();Model.upsert(d,"orders",order(d));s.replace(d);File f=s.backup();s.change(next->Model.find(next,"clients","client-a").put("city","Омск"));Store reopened=new Store(c);assertEquals("Омск",Model.s(Model.find(reopened.data,"clients","client-a"),"city"));JSONObject prior;try(InputStream in=new FileInputStream(f)){prior=Store.parse(Store.read(in));}reopened.replace(prior);assertEquals("Москва",Model.s(Model.find(reopened.data,"clients","client-a"),"city"));}
 @Test public void notificationAndSchedule()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();assertTrue(Reminders.enabled(c));Reminders.test(c);assertTrue(java.util.Arrays.stream(c.getSystemService(NotificationManager.class).getActiveNotifications()).anyMatch(n->"test".equals(n.getTag())));Reminders.refresh(c);assertEquals("",c.getSharedPreferences("reminders",0).getString("error",""));}
}
